569	                saleBid.updateStatus(BidStatus.COMPLETED);
570	            }
571	
572	            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);
573	
574	        } catch (Exception e) {
575	            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);
576	            // 상태 변경 실패는 로그만 남기고 진행 (주요 로직에 영향 주지 않음)
577	        }
