193	
194	        try {
195	            // OrderBid 조회
196	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
197	                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));
198	
199	            Order order = orderBid.getOrder();
